def _group(items):
    li = []
    for label, url in items:
        ext = url.startswith("http")
        attrs = ' rel="noopener" target="_blank"' if ext else ""
        li.append(f'<li><a href="{e(url)}"{attrs}>{e(label)}</a></li>')
    return '<ul class="checklist cols-2">' + "".join(li) + "</ul>"


